/**
 * Example: generating an EPUB from DITA.
 * This code demonstrates the plugin's Java utilities.
 */
public class EpubExample {
    public static void main(String[] args) {
        String input = "mybook.ditamap";
        String output = "mybook.epub";

        // The transformation is handled by DITA-OT
        System.out.println("Transforming: " + input);
        System.out.println("Output: " + output);

        for (int i = 0; i < 3; i++) {
            processChapter(i);
        }
    }
}
